/**
 * @name Unsafe dynamic attribute access
 * @description Using getattr/setattr with untrusted input can lead to unauthorized access
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-dynamic-attribute-access
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UnsafeAttrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["getattr", "setattr", "delattr", "hasattr"]).getACall() and
      sink = call.getArg(1)
    )
  }
}

module UnsafeAttrFlow = TaintTracking::Global<UnsafeAttrConfig>;
import UnsafeAttrFlow::PathGraph

from UnsafeAttrFlow::PathNode source, UnsafeAttrFlow::PathNode sink
where UnsafeAttrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe dynamic attribute access from $@.", source.getNode(), "user input"

/**
 * @name Dynamic import with user input
 * @description Using __import__ or importlib with user-controlled input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity high
 * @id py/dynamic-import
 * @tags security
 *        external/cwe/cwe-94
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module DynamicImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param | source = param)
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("__import__").getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("importlib").getMember("import_module").getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module DynamicImportFlow = TaintTracking::Global<DynamicImportConfig>;
import DynamicImportFlow::PathGraph

from DynamicImportFlow::PathNode source, DynamicImportFlow::PathNode sink
where DynamicImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic import with potentially user-controlled input from $@.", source.getNode(), "parameter"
